 val=parseInt(val);
 var max=0;
 for (i in sel.options) {
  //if (!(parseInt(sel.options[i].value)>0)) { continue; }
  if (parseInt(sel.options[i].value)==val) { sel.value=val; return val; }
  if (parseInt(sel.options[i].value)<val && parseInt(sel.options[i].value)>max) { max=parseInt(sel.options[i].value); }
 } // for
 sel.value=max;
 return max;
}

function set_ceil(id, val) {
 var sel=document.getElementById(id);
 if (val=='[zero]') { sel.value=val; }
 val=parseInt(val);
 var max=0;
 for (i in sel.options) {
  //if (!(parseInt(sel.options[i].value)>0)) { continue; }
  if (parseInt(sel.options[i].value)==val) { sel.value=val; return val; }
  if (parseInt(sel.options[i].value)>val && parseInt(sel.options[i].value)<max || max==0 || max<val) { max=parseInt(sel.options[i].value); }
 } // for
 if (max==0) {
  set_floor(id, val);
  return -1;
 }
 sel.value=max;
 return max;
}

